    function openCatalogItem(type,code){const x=catalogRecord(type,code);if(!x)return;if(currentView==='labor')laborState.current=x;else itemState.current=x;$('#dName').textContent=`${x.c} - ${x.d}`;$('#copyContact').style.display='none';$('#drawerShortlist').style.display='none';const evidence=x.laborEligible?laborEvidence(x):null,linkedIds=evidence?evidence.sids:x.sids;const supplierLinks=type==='item'&&linkedIds.length?linkedIds.map(id=>{const s=supplierById.get(String(id));return quotationEligible(s)?`<div class="supplier-link"><div><b>${esc(s.tradeName||s.legalName)}</b><span>${esc(s.city||'Localidade não informada')} · ${fmt(s.movements)} movimentos · ${esc(supplierIssueStatus(s.id))}</span></div><button class="btn" onclick="openSupplier(${s.id})">Abrir fornecedor</button></div>`:''}).join(''):'<span class="small muted">Nenhum fornecedor histórico vinculado neste conjunto de dados.</span>';$('#drawerBody').innerHTML=`<div class="detail-grid"><div class="detail"><span>Tipo</span><b>${type==='service'?'Serviço / composição':esc(x.cat)}</b></div><div class="detail"><span>Unidade</span><b>${esc(x.u||x.unit||'—')}</b></div><div class="detail full"><span>Grupo / etapa</span><b>${esc(x.g||x.sub||x.stage||'—')}</b></div>${x.specification?`<div class="detail full"><span>Especificação técnica</span><b>${esc(x.specification)}</b></div>`:''}<div class="detail"><span>Status cadastral</span><b>Não informado no relatório</b></div><div class="detail"><span>Status operacional</span><b>${esc(evidence?.contracts.length?'Com vínculo em '+evidence.contracts.length+' registros contratuais; conferir situações abaixo':x.status)}</b></div><div class="detail"><span>Duplicidade</span><b>${x.dups.length?esc(x.dups.join(', ')):'Sem alerta'}</b></div><div class="detail"><span>${type==='service'?'Obras vinculadas':'Último uso'}</span><b>${type==='service'?fmt(x.works):fmtDate(evidence?.last||x.last)}</b></div></div><h3 class="section-title">Fornecedores existentes na base</h3><p class="small muted">Abra o cadastro do fornecedor para registrar ou consultar ocorrencias. Os alertas tambem aparecem na aba Necessidades.</p><div class="supplier-links">${supplierLinks}</div>${x.laborEligible?laborContractDetails(x):''}<h3 class="section-title">Pesquisa externa</h3><button class="btn primary" onclick="researchCatalog('${type}','${x.c}')">Pesquisar ${type==='service'?'empreiteiros e prestadores':'fornecedores'} na internet</button>`;$('#drawer').classList.add('open');$('#drawerBackdrop').classList.add('open');}
    function laborContractDetails(x){const contracts=catalogContractEvidence(x);return '<h3 class="section-title">Contratos com vínculo exato ao insumo '+esc(x.c)+'</h3><p class="small muted">Vínculo por código e descrição do item contratual importado. O histórico inclui contratos rescindidos e fornecedores fora da lista ativa; esses registros não são recomendações para cotação.</p>'+(contracts.length?'<div class="supplier-links">'+contracts.map(c=>'<div class="supplier-link"><div><b>'+esc(c.n+' · '+c.sn)+'</b><span>'+esc(c.w+' · '+fmtDate(c.date)+' · '+(c.siengeStatus||'Status não informado'))+'</span><span>'+esc(quotationEligible(supplierById.get(String(c.sid)))&&contractEvidenceEligible(c)?'Fornecedor ativo; vínculo válido para referência':'Somente histórico; vínculo não elegível para recomendação')+'</span></div><button class="btn" onclick="openContract(decodeURIComponent(\''+encodeURIComponent(c.id)+'\'))">Abrir contrato</button></div>').join('')+'</div>':'<p class="catalog-note warn">Sem vínculo contratual exato nos itens disponíveis. Há contratos sem detalhamento importado; não é possível concluir que este insumo nunca foi contratado.</p>');}
