    function updateContractWorkLabel(){const selected=contractState.works;$('#cWorkLabel').textContent=selected.length===0?'Todas as obras':selected.length===1?selected[0]:selected.length+' obras selecionadas';$('#cWorkTrigger').title=selected.length?selected.join(' | '):'Todas as obras'}
