    function addIndicatedNeedRow(){const wrap=$('#needIndicatedRows');if(wrap.children.length>=10){toast('Limite de 10 fornecedores indicados.');return}const row=document.createElement('div');row.className='split-actions';row.style='justify-content:flex-start;flex-wrap:wrap;margin-bottom:6px';row.innerHTML='<input class="input" placeholder="Fornecedor indicado" aria-label="Fornecedor indicado" style="flex:1;min-width:170px"><input class="input" placeholder="Contato (telefone / e-mail)" aria-label="Contato do indicado" style="flex:1;min-width:130px"><input class="input" placeholder="Quem indicou" aria-label="Quem indicou" style="flex:1;min-width:130px"><button class="btn" type="button" aria-label="Remover indicação">×</button>';row.querySelector('button').onclick=()=>row.remove();wrap.append(row)}
