    function planFromContract(id){const x=contractHistory.find(c=>c.id===id);if(!x)return;const f=$('#needForm');f.elements.work.value=x.w;f.elements.classification.value=x.class;f.elements.scope.value=x.scope.split(' | ')[0];f.elements.leadDays.value=30;closeDrawer();setView('needs');updateNeedReferences();f.elements.activity.focus();}
    const toISODate=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
    function quoteByDate(needDate,leadDays){if(!needDate)return'';const d=new Date(`${needDate}T12:00:00`);d.setDate(d.getDate()-Number(leadDays||0));return toISODate(d)}
    function needAlert(n){if(['Contratado','Concluído'].includes(n.status))return{label:'Concluído',className:'ok'};if(!n.quoteBy)return{label:'Preencher datas',className:'soon'};const today=toISODate(new Date()),days=Math.ceil((new Date(`${n.quoteBy}T12:00:00`)-new Date(`${today}T12:00:00`))/86400000);if(days<0)return{label:`Atrasado ${Math.abs(days)} dias`,className:'overdue'};if(days<=15)return{label:`Iniciar em ${days} dias`,className:'soon'};return{label:'Planejado',className:'ok'}}
