    function exportNeedSheet(i){const n=needsList[i];if(!n)return;const material=needsList.find(x=>x.id===n.linkedMaterialId);const safe=v=>esc(String(v??''));const supplierRows=(n.references||[]).map(v=>{const id=String(v).split(' - ')[0];const su=suppliers.find(x=>String(x.id)===id);return `<tr><td>${safe(su?.legalName||su?.tradeName||v)}</td><td>${safe(su?.phone||'Não informado')}</td><td>${safe(su?.email||'Não informado')}</td><td>Histórico Lupema</td></tr>`}).join('');const extRows=(n.externalReferences||[]).map(x=>`<tr><td>${safe(x.name)}</td><td colspan="2">${safe(x.contact||'Não informado')}</td><td>${safe(x.url)}</td></tr>`).join('');const indRows=(n.indicatedReferences||[]).map(x=>`<tr><td>${safe(x.name)}</td><td colspan="2">${safe(x.contact||'Não informado')}</td><td>Indicação: ${safe(x.indicatedBy||'Não informado')}</td></tr>`).join('');const html=`<!doctype html><html lang="pt-BR"><meta charset="utf-8"><title>Necessidade ${safe(n.id)}</title><style>body{font:14px Arial,sans-serif;margin:35px;color:#20332b}h1{color:#116a4e}h2{margin-top:26px}table{border-collapse:collapse;width:100%}td,th{padding:9px;border-bottom:1px solid #ddd;text-align:left;vertical-align:top}small{color:#666}header{border-bottom:3px solid #137a59;padding-bottom:12px}@media print{button{display:none}}</style><header><h1>Lupema Suprimentos — Necessidade de contratação</h1><small>Ficha para obra e cotação · ${safe(n.id)}</small></header><p><b>Obra:</b> ${safe(n.work)} | <b>Atividade:</b> ${safe(n.activity)} | <b>Natureza:</b> ${safe(n.classification)}</p><p><b>Escopo:</b> ${safe(n.scope)}</p><p><b>Data necessária na obra:</b> ${safe(fmtDate(n.needDate))} | <b>Lead time:</b> ${safe(n.leadDays)} dias corridos | <b>Prazo-limite de contratação/documentação:</b> ${safe(fmtDate(n.quoteBy))}</p><p><b>Quantidade estimada:</b> ${safe(n.quantityEstimate??'A validar')} | <b>Status:</b> ${safe(n.status)} | <b>Restrição:</b> ${safe(n.restriction)}</p><p><b>Materiais vinculados:</b> ${material?safe(material.scope+' — '+material.status+' — necessidade '+fmtDate(material.needDate)):'Não vinculados'} (confirmar entrega física antes de iniciar)</p><h2>Fornecedores históricos</h2><table><tr><th>Fornecedor</th><th>Telefone</th><th>E-mail</th><th>Origem</th></tr>${supplierRows||'<tr><td colspan="4">Nenhum selecionado</td></tr>'}</table><h2>Referências pesquisadas na internet</h2><table><tr><th>Fornecedor</th><th colspan="2">Contato</th><th>Link</th></tr>${extRows||'<tr><td colspan="4">Nenhuma</td></tr>'}</table><h2>Fornecedores indicados</h2><table><tr><th>Fornecedor</th><th colspan="2">Contato</th><th>Quem indicou</th></tr>${indRows||'<tr><td colspan="4">Nenhum</td></tr>'}</table><p><b>Responsável:</b> ${safe(n.owner)} | <b>Próxima ação:</b> ${safe(n.notes)}</p><small>Dados locais do protótipo; confirmar contatos e documentação antes da cotação.</small><p><button onclick="print()">Imprimir / Salvar como PDF</button></p></html>`;const blob=new Blob([html],{type:'text/html;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='necessidade_'+String(n.id).replace(/[^a-zA-Z0-9_-]/g,'_')+'.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
    async function completeNeed(i){needsList[i].status='Concluído';await saveNeeds();toast('Necessidade concluída.')}
    async function removeNeed(i){needsList.splice(i,1);await saveNeeds();toast('Necessidade removida.')}
    // Índice por fornecedor: somente vínculos documentados nos relatórios importados.
    const supplierInsumoIndex=new Map();
    function addSupplierInsumo(sid,description){if(!sid||!description)return;const key=String(sid);if(!supplierInsumoIndex.has(key))supplierInsumoIndex.set(key,new Set());supplierInsumoIndex.get(key).add(norm(description));}
    catalogItems.concat(catalogServices).forEach(item=>{(item.sids||[]).forEach(sid=>addSupplierInsumo(sid,[item.c,item.d,item.syn||''].join(' ')));});
    Object.entries(PO_LINKS).forEach(([code,rows])=>{const item=catalogItems.find(x=>String(x.c)===String(code));(rows||[]).forEach(row=>addSupplierInsumo(row[0],[code,item?.d||''].join(' ')));});
    contractHistory.forEach(c=>{(c.items||[]).forEach(item=>addSupplierInsumo(c.sid,[item.c||'',item.d||''].join(' ')));});
    // Classes de credores: catálogo da planilha, complementado por classes já presentes na base.
