    let creditorClassCustom=store.get('lupemaCreditorClassCustomV1','[]');
    let creditorClassUpdates=store.get('lupemaCreditorClassUpdatesV1','{}');
    const allCreditorClasses=()=>[...new Set([...creditorClassSeed,...suppliers.flatMap(s=>s.classesOfficial||[]),...creditorClassCustom])].sort((a,b)=>a.localeCompare(b,'pt-BR',{numeric:true}));
    function classOptionsHtml(selected=[]){const set=new Set(selected);return allCreditorClasses().map(c=>`<label style="display:flex;gap:8px;align-items:flex-start;padding:5px 2px"><input type="checkbox" class="creditor-class-check" value="${esc(c)}" ${set.has(c)?'checked':''}><span>${esc(c)}</span></label>`).join('');}
    function classEditorHtml(s){return `<h3 class="section-title">Classes de credores (base compartilhada)</h3><p class="small muted">Selecione uma ou mais classes. As classes importadas do Sienge permanecem preservadas na base original.</p><input class="input" id="supplierClassSearch" placeholder="Filtrar classes por código ou descrição" oninput="filterCreditorChecks(this.value)"><div id="supplierClassChecks" style="max-height:225px;overflow:auto;border:1px solid #dce2e5;border-radius:8px;padding:8px;margin:8px 0">${classOptionsHtml(s.classesOfficial||[])}</div><button class="btn" type="button" onclick="openCreditorClassManager()">+ Cadastrar nova classe</button> <button class="btn primary" type="button" onclick="saveSupplierClasses(${Number(s.id)})">Salvar classes do fornecedor</button>`;}
    function filterCreditorChecks(q){document.querySelectorAll('#supplierClassChecks label').forEach(x=>x.hidden=!containsTokens(x.textContent,q));}
    async function saveSupplierClasses(id){const s=supplierById.get(String(id));if(!s)return;const selected=[...document.querySelectorAll('#supplierClassChecks input:checked')].map(x=>x.value);creditorClassUpdates[String(id)]=selected;await store.set('lupemaCreditorClassUpdatesV1',creditorClassUpdates);s.classesOfficial=selected;s.classes=selected.map(x=>x.replace(/^\d+\s*-\s*/, '')).join(', ');s._text=norm([s.legalName,s.tradeName,s.document,s.classes,s.city,s.contact,s.phone,s.email,s.representative,s.businessType,s.labor?.services,s.labor?.projects].join(' '));openSupplier(id);render();toast('Classes atualizadas para toda a equipe.');}
    async function openCreditorClassManager(){const value=prompt('Nova classe de credor (descrição; código opcional):');if(value===null)return;const v=value.trim().replace(/\s+/g,' ');if(!v){toast('Informe a classe.');return;}if(allCreditorClasses().some(x=>norm(x)===norm(v))){toast('Essa classe já está cadastrada.');return;}creditorClassCustom.push(v);await store.set('lupemaCreditorClassCustomV1',creditorClassCustom);const checks=$('#supplierClassChecks');if(checks){const current=[...checks.querySelectorAll('input:checked')].map(x=>x.value);current.push(v);checks.innerHTML=classOptionsHtml(current);}refreshLeadClassLists();if($('#quickClassChoices')){window.quickClassSelected?.add(v);renderQuickClasses();}toast('Nova classe cadastrada na base compartilhada.');}
    function refreshLeadClassLists(){document.querySelectorAll('.lead-creditor-class').forEach(sel=>{const value=sel.value;sel.innerHTML='<option value="">Selecione uma classe (opcional)</option>'+allCreditorClasses().map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');sel.value=value;});}
    allSuppliers.forEach(s=>{if(Object.prototype.hasOwnProperty.call(creditorClassUpdates,String(s.id))){s.classesOfficial=creditorClassUpdates[String(s.id)];s.classes=s.classesOfficial.map(x=>x.replace(/^\d+\s*-\s*/, '')).join(', ');s._text=norm([s.legalName,s.tradeName,s.document,s.classes,s.city,s.contact,s.labor?.services,s.labor?.projects].join(' '));}});
    const supplierContactUpdates=store.get('lupemaSupplierContactUpdatesV1','{}');
    allSuppliers.forEach(s=>{const update=supplierContactUpdates[String(s.id)];if(update){s.phone=update.phone||'';s.email=update.email||'';s.representative=update.representative||'';s.businessType=update.businessType||s.businessType||'';s.contact=update.contact||s.contact;}});
    async function saveSupplierContactUpdate(id){const s=supplierById.get(String(id));if(!s)return;const phone=$('#supplierEditPhone').value.trim(),email=$('#supplierEditEmail').value.trim(),representative=$('#supplierEditRepresentative').value.trim(),businessType=$('#supplierEditBusinessType').value;if(email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){toast('Confira o formato do e-mail.');return;}const entry={phone,email,representative,businessType,updatedAt:new Date().toISOString()};supplierContactUpdates[String(id)]=entry;await store.set('lupemaSupplierContactUpdatesV1',supplierContactUpdates);s.phone=phone;s.email=email;s.representative=representative;s.businessType=businessType;s._text=norm([s.legalName,s.tradeName,s.document,s.classes,s.city,s.contact,s.phone,s.email,s.representative,s.businessType,s.labor?.services,s.labor?.projects].join(' '));openSupplier(s.id);render();toast('Atualização cadastral salva na base compartilhada.');}
    function supplierContactEditor(s){return `<h3 class="section-title">Atualização cadastral (base compartilhada)</h3><div class="detail-grid"><div class="detail"><label for="supplierEditPhone">Telefone</label><input class="input" id="supplierEditPhone" value="${esc(s.phone||'')}" placeholder="DDD + número"></div><div class="detail"><label for="supplierEditEmail">E-mail</label><input class="input" id="supplierEditEmail" type="email" value="${esc(s.email||'')}" placeholder="contato@empresa.com.br"></div><div class="detail full"><label for="supplierEditRepresentative">Representante / contato comercial</label><input class="input" id="supplierEditRepresentative" value="${esc(s.representative||'')}" placeholder="Nome do representante"></div><div class="detail full"><label for="supplierEditBusinessType">Perfil comercial</label><select class="select" id="supplierEditBusinessType">${["","Fabricante / fábrica","Comércio local","Distribuidor / atacadista","Prestador de serviços","Outro"].map(v=>`<option value="${esc(v)}" ${s.businessType===v?"selected":""}>${esc(v||"Não informado")}</option>`).join("")}</select></div></div><p class="small muted">Alterações compartilhadas com a equipe; não atualizam o cadastro oficial no Sienge.</p><button class="btn primary" type="button" onclick="saveSupplierContactUpdate(${Number(s.id)})">Salvar atualização cadastral</button>`;}
    // Visao unificada: fornecedores prospectados sao projetados em memoria,
    // sem alterar os registros importados do Sienge nem duplicar os dados compartilhados.
    function projectedLeads(){return leads.map((l,i)=>{
      const classes=Array.isArray(l.creditorClasses)?l.creditorClasses:(l.creditorClass?[l.creditorClass]:[]);
      const linked=Array.isArray(l.linkedItems)?l.linkedItems:[];
      const isLabor=linked.some(x=>/servi|m[aã]o de obra/i.test(String(x.kind||'')))||/prestador|m[aã]o de obra/i.test(String(l.businessType||'')+' '+String(l.segment||''));
      const evaluated=['technicalRating','serviceRating','commercialRating','documentationRating'].some(k=>Number(l[k])>=1&&Number(l[k])<=5);
      const name=l.name||l.tradeName||'Fornecedor prospectado';
      return {id:-(i+1),_leadIndex:i,_isLead:true,siengeRegistration:l.siengeRegistration||'Pendente de cadastro no Sienge',legalName:name,tradeName:l.tradeName||name,document:l.document||'',classesOfficial:classes,classes:classes.join(', '),city:l.location||'',state:l.state||'',status:l.status||'Prospectado',evaluation:evaluated?'Avaliado':'Não avaliado',isLabor,phone:l.phone||'',email:l.email||'',contact:l.contact||l.representative||'',representative:l.representative||'',movements:0,lastMovement:'',updatedAt:l.capturedAt||'',updatedBy:l.evaluationBy||'',_text:norm([name,l.tradeName,l.document,l.location,l.state,l.phone,l.email,l.representative,l.segment,l.businessType,classes.join(' '),linked.map(x=>[x.code,x.name].join(' ')).join(' ')].join(' ')),_linkedItems:linked};
    })}
    function unifiedSuppliers(){
      // A base oficial nunca depende de um cadastro prospectado para ser exibida.
      try {return suppliers.concat(projectedLeads())}
      catch(err){console.error('Falha ao projetar prospectados:',err);return suppliers}
    }
    function score(s){let v=0;const tokens=norm(state.query).split(/\s+/).filter(Boolean);if(tokens.length){const hit=tokens.filter(t=>containsTokens(s._text,t)).length;if(hit<tokens.length)return -1;v+=Math.round(45*hit/tokens.length);if(containsTokens(s.classes,state.query))v+=12;if(containsTokens(s.tradeName,state.query))v+=8;}else v+=12;if(s.status==='Ativo')v+=10;if(s.evaluation==='Avaliado')v+=10;if(s.movements>0)v+=Math.min(12,Math.round(Math.log2(s.movements+1)*2));if(monthsSince(s.lastMovement)<=24)v+=7;if(s.phone||s.email)v+=4;if(s.isLabor&&state.segment==='labor')v+=5;return Math.min(100,v);}
